import os
from pathlib import Path
import subprocess
import sys

JAVASCRIPT = "import { pathToFileURL } from 'node:url';\nimport { resolve } from 'node:path';\n\nconst { createApplication } = await import(pathToFileURL(resolve(process.argv[1], 'app.mjs')).href);\n\nfunction setup(body, line) {\n  const app = createApplication();\n  function call(action, input) {\n    const response = app.dispatch(action, input, 'admin');\n    if (!response.ok) throw new Error(`Public setup ${action} failed: ${JSON.stringify(response.error)}`);\n    return response.data;\n  }\n  const collection = call('collections.create', { name: 'Position review' });\n  const item = call('documents.create', { collectionId: collection.id, title: 'Source coordinates', body });\n  const comment = call('comments.add', { documentId: item.id, line, body: 'Check this instruction.' });\n  return { app, call, item, comment };\n}\n\nfunction rangeData(range) {\n  return { startLine: range.startLine, endLine: range.endLine, start: range.start, end: range.end, quote: range.quote };\n}\n\nfunction captureData(response) {\n  return response.ok ? { ok: true, range: rangeData(response.data.range) }\n    : { ok: false, error: response.error.code };\n}\n\nfunction captureCase(body, line) {\n  const { app, item, comment } = setup(body, line);\n  const response = app.dispatch('structure.anchors.capture', { documentId: item.id,\n    commentId: comment.id, expectedChecksum: item.revision.checksum }, 'admin');\n  const state = app.inspect();\n  return { capture: captureData(response), commentUnchanged: JSON.stringify(state.comments[comment.id]) === JSON.stringify(comment),\n    revisionUnchanged: JSON.stringify(state.revisions[item.revision.id]) === JSON.stringify(item.revision) };\n}\n\nconst primary = setup('Header\\rSubheading\\nTarget\\n', 2);\nconst captured = primary.app.dispatch('structure.anchors.capture', { documentId: primary.item.id,\n  commentId: primary.comment.id, expectedChecksum: primary.item.revision.checksum }, 'admin');\nconst beforeGuard = primary.app.inspect();\nconst guarded = primary.app.dispatch('structure.anchors.capture', { documentId: primary.item.id,\n  commentId: primary.comment.id, expectedChecksum: primary.item.revision.checksum, expectedQuote: 'Target\\n' }, 'admin');\nconst afterGuard = primary.app.inspect();\n\nconst moved = setup('Header\\nTarget\\n', 2);\nconst originalAnchor = moved.call('structure.anchors.capture', { documentId: moved.item.id,\n  commentId: moved.comment.id, expectedChecksum: moved.item.revision.checksum });\nconst revised = moved.call('documents.revise', { id: moved.item.id, body: 'Header\\rSubheading\\nTarget\\n' });\nconst preview = moved.app.dispatch('structure.anchors.preview', { documentId: moved.item.id, anchorIds: [originalAnchor.id] }, 'admin');\nconst followup = moved.app.dispatch('structure.anchors.followup', { documentId: moved.item.id,\n  expectedRevisionId: revised.revision.id, expectedChecksum: revised.revision.checksum,\n  entries: [{ anchorId: originalAnchor.id, body: 'The question remains.' }] }, 'admin');\nconst mapping = preview.ok ? preview.data.mappings[0] : null;\nconst created = followup.ok ? followup.data[0] : null;\nconst movedState = moved.app.inspect();\n\nprocess.stdout.write(JSON.stringify({\n  schema: 1,\n  primary: {\n    sourceComment: { line: primary.comment.line, revisionMatchesDocument: primary.comment.revisionId === primary.item.revision.id },\n    capture: captureData(captured),\n    guardedCapture: captureData(guarded),\n    guardedEffects: {\n      anchors: Object.keys(afterGuard.structureAnchors).length - Object.keys(beforeGuard.structureAnchors).length,\n      events: afterGuard.events.length - beforeGuard.events.length,\n      sequence: afterGuard.sequence - beforeGuard.sequence,\n      stateUnchanged: JSON.stringify(afterGuard) === JSON.stringify(beforeGuard),\n    },\n    sourceCommentUnchanged: JSON.stringify(afterGuard.comments[primary.comment.id]) === JSON.stringify(primary.comment),\n    sourceRevisionUnchanged: JSON.stringify(afterGuard.revisions[primary.item.revision.id]) === JSON.stringify(primary.item.revision),\n  },\n  controls: {\n    lf: captureCase('Header\\nTarget\\n', 2),\n    crlfUnicode: captureCase('😀 Header\\r\\nTarget\\r\\n', 2),\n    empty: captureCase('', 1),\n    finalEmpty: captureCase('Header\\n', 2),\n    finalUnterminated: captureCase('Header\\nTarget', 2),\n  },\n  followup: {\n    preview: preview.ok ? { ok: true, status: mapping.status, exact: mapping.exact,\n      target: mapping.target === null ? null : rangeData(mapping.target) } : { ok: false, error: preview.error.code },\n    creation: created ? { ok: true, line: created.comment.line,\n      physicalLineText: revised.revision.body.split('\\n')[created.comment.line - 1],\n      targetQuote: created.link.targetRange.quote,\n      revisionMatchesCurrent: created.comment.revisionId === revised.revision.id,\n      sourceRevisionMatchesOriginal: created.link.sourceRevisionId === moved.item.revision.id }\n      : { ok: false, error: followup.error.code },\n    originalCommentUnchanged: JSON.stringify(movedState.comments[moved.comment.id]) === JSON.stringify(moved.comment),\n    originalRevisionUnchanged: JSON.stringify(movedState.revisions[moved.item.revision.id]) === JSON.stringify(moved.item.revision),\n  },\n}) + '\\n');\n"
root = Path(sys.argv[1]).resolve()
environment = {key: value for key, value in os.environ.items() if key not in ('NODE_OPTIONS', 'NODE_PATH')}
result = subprocess.run(['node', '--input-type=module', '-e', JAVASCRIPT, str(root)],
                        env=environment, capture_output=True, text=True, timeout=6)
sys.stdout.write(result.stdout)
sys.stderr.write(result.stderr)
sys.exit(result.returncode)
